import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // ключ берётся из ANTHROPIC_API_KEY
const MODEL = "claude-opus-5-5"; // актуальные ID моделей смотри в документации

const tools: Anthropic.Tool[] = [
  {
    name: "fetch_url",
    description:
      "Downloads a web page and returns its raw text (HTML included), cut to 20,000 characters. " +
      "Use it when you already have a specific URL and need its contents. " +
      "Do not use it to search: it cannot find pages, only read one you name. " +
      "Returns the server's response body even for error pages.",
    input_schema: {
      type: "object",
      properties: {
        url: { type: "string", description: "Absolute http(s) URL, e.g. https://example.com/page" },
      },
      required: ["url"],
    },
  },
];

// «Руки»: в сеть ходит твой код, а не модель.
async function runTool(name: string, input: unknown): Promise<string> {
  if (name === "fetch_url") {
    const { url } = input as { url: string }; // в реальном коде валидируй (например, zod)
    const res = await fetch(url);
    return (await res.text()).slice(0, 20_000);
  }
  throw new Error("Unknown tool: " + name);
}

async function agent(question: string): Promise<string> {
  const messages: Anthropic.MessageParam[] = [{ role: "user", content: question }];

  while (true) {
    const response = await client.messages.create({ model: MODEL, max_tokens: 2048, tools, messages });
    // 1. Сохраняем ход ассистента как есть, со всеми блоками.
    messages.push({ role: "assistant", content: response.content });

    // 2. Запроса инструмента нет: это финальный ответ.
    if (response.stop_reason !== "tool_use") {
      return response.content.filter((b) => b.type === "text").map((b) => b.text).join("");
    }

    // 3. Исполняем каждый tool_use, на каждый отвечаем tool_result.
    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type !== "tool_use") continue;
      const output = await runTool(block.name, block.input);
      results.push({ type: "tool_result", tool_use_id: block.id, content: output });
    }
    // 4. Все результаты в ОДНОМ сообщении user, и снова в цикл.
    messages.push({ role: "user", content: results });
  }
}

